62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    private final OwnerFieldsValidator ownerFieldsValidator;
81	
82	    private final PostcodeValidator postcodeValidator;
83	
84	    private final TelephoneNormalizer telephoneNormalizer;
85	
86	    private final EmailNormalizer emailNormalizer;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    private final IdentityDuplicateValidator identityDuplicateValidator;
91	
92	    private final PossibleDuplicateDetector possibleDuplicateDetector;
93	
94	    private final HouseholdAssigner householdAssigner;
95	
96	    private final CityCapacityValidator cityCapacityValidator;
97	
98	    private final DailyRegistrationLimitValidator dailyRegistrationLimitValidator;
99	
100	    private final BusinessDayAdjuster businessDayAdjuster;
101	
102	    private final RegistrationDateValidator registrationDateValidator;
103	
104	    private final OwnerAuditLogger ownerAuditLogger;
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper,
110	                                 OwnerFieldsValidator ownerFieldsValidator,
111	                                 PostcodeValidator postcodeValidator,
112	                                 TelephoneNormalizer telephoneNormalizer,
113	                                 EmailNormalizer emailNormalizer,
114	                                 AddressNormalizer addressNormalizer,
115	                                 IdentityDuplicateValidator identityDuplicateValidator,
116	                                 PossibleDuplicateDetector possibleDuplicateDetector,
117	                                 HouseholdAssigner householdAssigner,
118	                                 CityCapacityValidator cityCapacityValidator,
119	                                 DailyRegistrationLimitValidator dailyRegistrationLimitValidator,
120	                                 BusinessDayAdjuster businessDayAdjuster,
121	                                 RegistrationDateValidator registrationDateValidator,
122	                                 OwnerAuditLogger ownerAuditLogger) {
123	        this.clinicService = clinicService;
124	        this.ownerMapper = ownerMapper;
125	        this.petMapper = petMapper;
126	        this.visitMapper = visitMapper;
127	        this.ownerFieldsValidator = ownerFieldsValidator;
128	        this.postcodeValidator = postcodeValidator;
129	        this.telephoneNormalizer = telephoneNormalizer;
130	        this.emailNormalizer = emailNormalizer;
131	        this.addressNormalizer = addressNormalizer;
132	        this.identityDuplicateValidator = identityDuplicateValidator;
133	        this.possibleDuplicateDetector = possibleDuplicateDetector;
134	        this.householdAssigner = householdAssigner;
135	        this.cityCapacityValidator = cityCapacityValidator;
136	        this.dailyRegistrationLimitValidator = dailyRegistrationLimitValidator;
137	        this.businessDayAdjuster = businessDayAdjuster;
138	        this.registrationDateValidator = registrationDateValidator;
139	        this.ownerAuditLogger = ownerAuditLogger;
140	    }
141	
142	    /**
143	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
144	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
145	     */
146	    @InitBinder("ownerFieldsDto")
147	    void initOwnerFieldsBinder(WebDataBinder binder) {
148	        binder.addValidators(ownerFieldsValidator, postcodeValidator);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Override
153	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
154	        Collection<Owner> owners;
155	        if (lastName != null) {
156	            owners = this.clinicService.findOwnerByLastName(lastName);
157	        } else {
158	            owners = this.clinicService.findAllOwners();
159	        }
160	        if (owners.isEmpty()) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Override
178	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
182	        registrationDateValidator.validate(owner.getRegistrationDate());
183	        LocalDate registrationDate = owner.getRegistrationDate() != null
184	            ? owner.getRegistrationDate() : LocalDate.now();
185	        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(registrationDate));
186	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
187	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
188	        dailyRegistrationLimitValidator.validate(owner.getRegistrationDate());
189	        cityCapacityValidator.validate(owner);
190	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
191	            householdAssigner.assignSharedHousehold(owner);
192	        }
193	        identityDuplicateValidator.validate(owner);
194	        possibleDuplicateDetector.detect(owner);
195	        this.clinicService.saveOwner(owner);
196	        ownerAuditLogger.logCreated(owner);
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
206	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
207	        if (currentOwner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        currentOwner.setAddress(ownerFieldsDto.getAddress());
211	        currentOwner.setCity(ownerFieldsDto.getCity());
212	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
