58	        if (candidate.getPostcode() == null) {
59	            return null;
60	        }
61	        return clinicService.findOwnerByLastNameIgnoreCase(candidate.getLastName()).stream()
62	            .filter(existing -> candidate.getPostcode().equals(existing.getPostcode()))
63	            .filter(existing -> !Objects.equals(candidate.getTelephone(), existing.getTelephone()))
